/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.7 Multimodal dangerous goods
/// As the standard field ShipmentId is mandatory and has a relation to standard table WHSShipmentTable, 
/// need to make sure it is updated with value from custom METShipmentId field
/// </summary>
internal final class METHMIMMultimodalDGEventHandler
{    
}

Method.Source:
    /// <summary>
    /// When called from sales order shipments and when the record is created initialize the standard field ShipmentId from custom METShipmentId field
    /// </summary>
    /// <param name="sender">Form datasource</param>
    /// <param name="e">Form datasource event args</param>
    [FormDataSourceEventHandler(formDataSourceStr(HMIMMultimodalDG, HMIMMultimodalDG), FormDataSourceEventType::Created),
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
    public static void HMIMMultimodalDG_OnCreated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        HMIMMultimodalDG HMIMMultimodalDG = sender.cursor();

        if (HMIMMultimodalDG.METShipmentId)
        {
            HMIMMultimodalDG.ShipmentId = HMIMMultimodalDG.METShipmentId;
        }
    }

    /// <summary>
    /// When custom METShipmentId field is changed, update the standard field ShipmentId with same value
    /// </summary>
    /// <param name="sender">Form data object</param>
    /// <param name="e">Form data field event args</param>
    [FormDataFieldEventHandler(formDataFieldStr(HMIMMultimodalDG, HMIMMultimodalDG, METShipmentId), FormDataFieldEventType::Modified),
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
    public static void ShipmentId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        HMIMMultimodalDG HMIMMultimodalDG = sender.dataSource().cursor();

        HMIMMultimodalDG.ShipmentId = HMIMMultimodalDG.METShipmentId;
    }
